{"files":[{"path":"src/test/java/com/example/shortener/controller/GlobalExceptionHandlerTest.java","content":"package com.example.shortener.controller;

import com.example.shortener.exception.CodeGenerationException;
import com.example.shortener.exception.InvalidUrlException;
import com.example.shortener.exception.LinkNotFoundException;
import com.example.shortener.service.AuditService;
import jakarta.servlet.http.HttpServletRequest;
import org.junit.jupiter.api.Test;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.boot.test.system.CapturedOutput;
import org.springframework.boot.test.system.OutputCaptureExtension;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.junit.jupiter.api.extension.ExtendWith;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.*;

@ExtendWith({MockitoExtension.class, OutputCaptureExtension.class})
class GlobalExceptionHandlerTest {
    @Mock AuditService audit;
    @Mock HttpServletRequest request;

    @Test
    void mapsInvalidCreationAndUnexpectedErrorsWithoutSensitiveDetails() {
        GlobalExceptionHandler handler = new GlobalExceptionHandler(audit);
        when(request.getRequestURI()).thenReturn("/api/links");
        when(request.getRemoteAddr()).thenReturn("127.0.0.1");

        ResponseEntity<?> invalid = handler.invalid(new InvalidUrlException("bad URL"), request);
        assertThat(invalid.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
        assertThat(invalid.getBody().toString()).contains("bad URL");
        verify(audit).recordFailure("CREATION_REJECTED", null, "127.0.0.1", "INVALID_URL:bad URL");

        ResponseEntity<?> unexpected = handler.unexpected(new IllegalStateException("secret database detail"));
        assertThat(unexpected.getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);
        assertThat(unexpected.getBody().toString()).doesNotContain("secret database detail");
    }

    @Test
    void handlesMalformedCreationRequestsAndOnlyAuditsCreationPaths() {
        GlobalExceptionHandler handler = new GlobalExceptionHandler(audit);
        when(request.getRequestURI()).thenReturn("/api/links");
        when(request.getRemoteAddr()).thenReturn("192.0.2.10");

        ResponseEntity<?> response = handler.badRequest(
                new HttpMessageNotReadableException("malformed", (org.springframework.http.HttpInputMessage) null), request);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
        verify(audit).recordFailure("CREATION_REJECTED", null, "192.0.2.10", "INVALID_REQUEST:request body is invalid");

        reset(audit);
        when(request.getRequestURI()).thenReturn("/other");
        handler.badRequest(new HttpMessageNotReadableException("malformed", (org.springframework.http.HttpInputMessage) null), request);
        verifyNoInteractions(audit);
    }

    @Test
    void mapsBeanValidationFailuresToAReadableBadRequest() {
        GlobalExceptionHandler handler = new GlobalExceptionHandler(audit);
        when(request.getRequestURI()).thenReturn("/api/links");
        when(request.getRemoteAddr()).thenReturn("192.0.2.11");

        ResponseEntity<?> response = handler.badRequest(mock(MethodArgumentNotValidException.class), request);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
        assertThat(response.getBody().toString()).contains("url must not be blank");
        verify(audit).recordFailure("CREATION_REJECTED", null, "192.0.2.11",
                "INVALID_REQUEST:url must not be blank");
    }

    @Test
    void mapsNotFoundAndProvidesOperationalErrorHandlingForAllKeyOutcomes() {
        GlobalExceptionHandler handler = new GlobalExceptionHandler(audit);
        ResponseEntity<?> response = handler.notFound(new LinkNotFoundException("missing"));
        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.NOT_FOUND);
        assertThat(response.getBody().toString()).contains("Short link not found");
    }

    @Test
    void mapsCodeGenerationExhaustionToServiceUnavailableWithoutInternalDetails() {
        GlobalExceptionHandler handler = new GlobalExceptionHandler(audit);

        ResponseEntity<?> response = handler.codeGeneration(new CodeGenerationException("collision details"));

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.SERVICE_UNAVAILABLE);
        assertThat(response.getBody().toString()).contains("Unable to create a short link");
        assertThat(response.getBody().toString()).doesNotContain("collision details");
    }

    @Test
    void logsUnexpectedRequestProcessingErrorsWithoutExposingTheExceptionMessage(CapturedOutput output) {
        GlobalExceptionHandler handler = new GlobalExceptionHandler(audit);

        ResponseEntity<?> response = handler.unexpected(new IllegalStateException("secret database detail"));

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);
        assertThat(output.getOut()).contains("Unexpected request-processing error")
                .doesNotContain("secret database detail");
    }

    @Test
    void returnsGenericFiveHundredProblemDetailForUnexpectedFailures(CapturedOutput output) {
        GlobalExceptionHandler handler = new GlobalExceptionHandler(audit);
        String sensitiveMessage = "password=do-not-disclose";

        ResponseEntity<?> response = handler.unexpected(new RuntimeException(sensitiveMessage));

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);
        assertThat(response.getBody()).isNotNull();
        assertThat(response.getBody().toString())
                .contains("An unexpected server error occurred")
                .doesNotContain(sensitiveMessage);
        assertThat(output.getOut()).contains("Unexpected request-processing error")
                .doesNotContain(sensitiveMessage);
    }
}
"},{"path":"src/test/java/com/example/shortener/UrlShortenerHttpIntegrationTest.java","content":"package com.example.shortener;

import com.example.shortener.domain.AuditEvent;
import com.example.shortener.repository.AuditEventRepository;
import com.example.shortener.repository.LinkRepository;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.system.CapturedOutput;
import org.springframework.boot.test.system.OutputCaptureExtension;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.junit.jupiter.api.extension.ExtendWith;

import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
@ExtendWith(OutputCaptureExtension.class)
class UrlShortenerHttpIntegrationTest {
    @Autowired MockMvc mvc;
    @Autowired LinkRepository links;
    @Autowired AuditEventRepository audits;

    @Test
    void createsDuplicateLinksWithSafeCodesAndAudits() throws Exception {
        String url = "https://example.com/duplicate-" + System.nanoTime();
        long beforeLinks = links.count();
        String first = mvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated()).andExpect(jsonPath("$.originalUrl").value(url))
                .andExpect(jsonPath("$.clickCount").value(0)).andReturn().getResponse().getContentAsString();
        String second = mvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
        String c1 = first.replaceAll(".*\"code\":\"([^\"]+)\".*", "$1");
        String c2 = second.replaceAll(".*\"code\":\"([^\"]+)\".*", "$1");
        assertThat(c1).matches("[A-Za-z0-9]{7}");
        assertThat(c2).matches("[A-Za-z0-9]{7}").isNotEqualTo(c1);
        assertThat(links.count()).isEqualTo(beforeLinks + 2);
        assertThat(audits.findAll().stream().filter(a -> a.getAction().equals("LINK_CREATED")).count())
                .isGreaterThanOrEqualTo(2);
    }

    @Test
    void rejectsInvalidRequestsAndPersistsRejectionAuditsWithoutCreatingLinks() throws Exception {
        long beforeLinks = links.count();
        long beforeAudits = audits.count();
        for (String body : new String[]{"{}", "{\"url\":\"/relative\"}", "{\"url\":\"ftp://example.com\"}", "{\"url\":\"http://exa mple.com\"}", "not-json"}) {
            mvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON).content(body))
                    .andExpect(status().isBadRequest()).andExpect(jsonPath("$.detail").exists());
        }
        assertThat(links.count()).isEqualTo(beforeLinks);
        List<AuditEvent> newAudits = audits.findAll().stream().skip(beforeAudits).toList();
        assertThat(newAudits).hasSize(5).allMatch(a -> a.getAction().equals("CREATION_REJECTED")
                && a.getCode() == null && a.getEventTime() != null && a.getClientIp() != null
                && a.getOutcome().contains("INVALID"));
    }

    @Test
    void rejectsOverlongDestinationWithValidationProblem() throws Exception {
        String url = "https://example.com/" + "x".repeat(2030);
        mvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").value("url must be an absolute HTTP or HTTPS URL"));
    }

    @Test
    void invalidShortCodeReturns404WithoutARedirectLocationAndPersistsUnknownAudit() throws Exception {
        long before = audits.count();
        mvc.perform(get("/not-valid"))
                .andExpect(status().isNotFound())
                .andExpect(header().doesNotExist("Location"));
        List<AuditEvent> events = audits.findAll().stream().skip(before).toList();
        assertThat(events).singleElement().satisfies(a -> {
            assertThat(a.getAction()).isEqualTo("UNKNOWN_CODE");
            assertThat(a.getCode()).isEqualTo("not-val");
            assertThat(a.getOutcome()).isEqualTo("NOT_FOUND");
            assertThat(a.getEventTime()).isNotNull();
            assertThat(a.getClientIp()).isNotNull();
        });
    }

    @Test
    void redirectsCountsClicksAndReturnsDetails() throws Exception {
        String url = "https://example.com/redirect-" + System.nanoTime();
        String body = mvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
        String code = body.replaceAll(".*\"code\":\"([^\"]+)\".*", "$1");
        mvc.perform(get("/" + code)).andExpect(status().isFound()).andExpect(header().string("Location", url));
        mvc.perform(get("/" + code)).andExpect(status().isFound());
        mvc.perform(get("/api/links/" + code)).andExpect(status().isOk())
                .andExpect(jsonPath("$.code").value(code)).andExpect(jsonPath("$.originalUrl").value(url))
                .andExpect(jsonPath("$.clickCount").value(2));
        List<AuditEvent> events = audits.findAll().stream().filter(a -> code.equals(a.getCode())).toList();
        assertThat(events).extracting(AuditEvent::getAction)
                .containsExactlyInAnyOrder("LINK_CREATED", "REDIRECTED", "REDIRECTED");
        assertThat(events).allMatch(a -> a.getEventTime() != null && a.getClientIp() != null && a.getOutcome() != null);
    }

    @Test
    void unknownCodesReturnProblemDetailsWithoutLocationHeadersAndPersistAudits() throws Exception {
        String code = "UNKNWN1";
        long before = audits.count();
        mvc.perform(get("/" + code)).andExpect(status().isNotFound()).andExpect(header().doesNotExist("Location"))
                .andExpect(jsonPath("$.detail").exists());
        mvc.perform(get("/api/links/" + code)).andExpect(status().isNotFound());
        List<AuditEvent> events = audits.findAll().stream().skip(before).toList();
        assertThat(events).hasSize(2).allMatch(a -> a.getAction().equals("UNKNOWN_CODE")
                && a.getCode().equals(code) && a.getOutcome().equals("NOT_FOUND")
                && a.getEventTime() != null && a.getClientIp() != null);
    }

    @Test
    void concurrentRedirectsDoNotLoseClickIncrements() throws Exception {
        String url = "https://example.com/concurrent-" + System.nanoTime();
        String body = mvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
        String code = body.replaceAll(".*\"code\":\"([^\"]+)\".*", "$1");
        int count = 8;
        ExecutorService pool = Executors.newFixedThreadPool(count);
        try {
            List<Future<Integer>> results = pool.invokeAll(java.util.stream.IntStream.range(0, count)
                    .mapToObj(i -> (java.util.concurrent.Callable<Integer>) () ->
                            mvc.perform(get("/" + code)).andReturn().getResponse().getStatus())
                    .toList());
            assertThat(results).allMatch(f -> {
                try { return f.get() == 302; } catch (Exception e) { return false; }
            });
        } finally {
            pool.shutdownNow();
        }
        mvc.perform(get("/api/links/" + code)).andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(count));
    }

    @Test
    void writesIdentifiableOperationalLogsForKeyOperations(CapturedOutput output) throws Exception {
        String url = "https://example.com/logging-" + System.nanoTime();
        String body = mvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
        String code = body.replaceAll(".*\"code\":\"([^\"]+)\".*", "$1");

        mvc.perform(post("/api/links").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"ftp://example.com\"}"))
                .andExpect(status().isBadRequest());
        mvc.perform(get("/" + code)).andExpect(status().isFound());
        mvc.perform(get("/ZZZZZZZ")).andExpect(status().isNotFound());

        assertThat(output.getOut()).contains("LINK_CREATED", "CREATION_REJECTED", "REDIRECTED", "UNKNOWN_CODE", code)
                .doesNotContain(url);
    }
}
